"""
12_write_results_evidence.py
Writes RESULTS_EVIDENCE.md from results/reported_numbers.csv (made by 11_reproduce_reported_numbers.py):
one row per number reported in the paper, the recomputed value, the source file and the status.
Usage (repository root): python scripts/4_revision_checks/12_write_results_evidence.py
"""
import pandas as pd

d = pd.read_csv("results/reported_numbers.csv", dtype=str).fillna("")
icon = {"match": "✅", "differs": "❌", "record only": "📄"}
lines = ["# Evidence for every reported number", "",
         "Generated by `scripts/4_revision_checks/12_write_results_evidence.py` from `results/reported_numbers.csv`,",
         "which `scripts/4_revision_checks/11_reproduce_reported_numbers.py` recomputes from the files in this repository.", "",
         f"**{(d.status == 'match').sum()} of {len(d)} numbers reproduce exactly.** "
         "Rows marked ❌ cannot yet be reproduced from the files here (see the note).", "",
         "Section numbers refer to the manuscript. Agreement values marked `results/from_step09/` come from "
         "`scripts/3_source_context/09_evaluate_against_human_reference.py`, which needs the saved page texts "
         "(not redistributed); its outputs are kept as the record.", ""]
for sec, g in d.groupby("section", sort=False):
    lines += [f"## {sec}", "", "| | Quantity | Recomputed | Paper | Source | Note |", "|---|---|---|---|---|---|"]
    for r in g.itertuples():
        lines.append(f"| {icon.get(r.status, '')} | {r.quantity} | {r.recomputed} | {r.paper} | `{r.source}` | {r.note} |")
    lines.append("")
open("RESULTS_EVIDENCE.md", "w", encoding="utf-8").write("\n".join(lines))
print("written RESULTS_EVIDENCE.md:", len(d), "rows")
